func:
// Génère une valeur aléatoire entre 0 et 100
var randomValue = Math.floor(Math.random() * 101);

// Création du timestamp Unix en millisecondes
var timestamp = Date.now();

// Format InfluxDB Line Protocol pour VictoriaMetrics
// Format: metric_name{tag1="value1"} value timestamp
var lineProtocol = 'nodered_test{source="nodered",host="windows_pc"} ' + randomValue + ' ' + timestamp;

msg.payload = lineProtocol;
msg.metricValue = randomValue;
msg.timestamp = timestamp;
msg.url = 'http://192.168.1.141:8428/api/v1/import/prometheus';

node.status({fill:"green",shape:"dot",text:"Valeur: " + randomValue});

return msg;

// Récupère le compteur global ou initialise à 0
var successCount = global.get('vm_success_count') || 0;
successCount++;
global.set('vm_success_count', successCount);

msg.payload = {
    status: "SUCCESS",
    statusCode: msg.statusCode,
    metricValue: msg.metricValue,
    timestamp: msg.timestamp,
    totalSuccess: successCount,
    responseBody: msg.payload,
    url: msg.url
};

node.status({fill:"green",shape:"dot",text:"OK #" + successCount});

return msg;

// Récupère le compteur d'erreurs
var errorCount = global.get('vm_error_count') || 0;
errorCount++;
global.set('vm_error_count', errorCount);

var errorDetails = {
    status: "ERROR",
    statusCode: msg.statusCode || "No Response",
    errorMessage: msg.payload || "Unknown error",
    metricValue: msg.metricValue,
    timestamp: msg.timestamp,
    totalErrors: errorCount,
    url: msg.url,
    headers: msg.headers || "N/A"
};

// Détection spécifique des erreurs
if (msg.statusCode === 400) {
    errorDetails.errorType = "BAD REQUEST - Format de données invalide";
} else if (msg.statusCode === 404) {
    errorDetails.errorType = "NOT FOUND - Endpoint incorrect";
} else if (msg.statusCode === 500) {
    errorDetails.errorType = "SERVER ERROR - Problème côté VictoriaMetrics";
} else if (!msg.statusCode) {
    errorDetails.errorType = "CONNECTION ERROR - Serveur injoignable";
} else {
    errorDetails.errorType = "UNKNOWN ERROR - Code: " + msg.statusCode;
}

msg.payload = errorDetails;

node.status({fill:"red",shape:"ring",text:"Erreur #" + errorCount});

return msg;

var successCount = global.get('vm_success_count') || 0;
var errorCount = global.get('vm_error_count') || 0;
var totalAttempts = successCount + errorCount;

msg.payload = {
    totalEnvoyes: totalAttempts,
    succes: successCount,
    erreurs: errorCount,
    tauxReussite: totalAttempts > 0 ? ((successCount / totalAttempts) * 100).toFixed(2) + '%' : 'N/A',
    derniereValeur: msg.metricValue || 'N/A',
    dernierStatut: msg.payload.status || 'N/A'
};

return msg;

// Requête pour vérifier si le metric existe et compter les données
var query = 'count(nodered_test)';

msg.method = "GET";
msg.url = 'http://192.168.1.141:8428/api/v1/query?query=' + encodeURIComponent(query);
msg.queryType = "count";

node.status({fill:"blue",shape:"dot",text:"Query..."});

return msg;

var response = msg.payload;
var result = {
    queryTime: new Date().toISOString(),
    rawResponse: response,
    status: response.status || "unknown"
};

if (response.status === "success" && response.data && response.data.result) {
    var results = response.data.result;

    if (results.length > 0) {
        var metricData = results[0];
        result.metricFound = true;
        result.metricName = "nodered_test";
        result.totalDataPoints = metricData.value ? metricData.value[1] : "N/A";
        result.timestamp = metricData.value ? new Date(parseInt(metricData.value[0]) * 1000).toISOString() : "N/A";
        result.labels = metricData.metric || {};

        // Comparer avec le nombre envoyé
        var sentCount = global.get('vm_success_count') || 0;
        result.sentByNodeRED = sentCount;
        result.receivedByVM = parseInt(result.totalDataPoints) || 0;
        result.difference = sentCount - result.receivedByVM;
        result.syncStatus = result.difference === 0 ? "✅ PARFAIT" : (result.difference > 0 ? "⚠️ PERTES DETECTEES" : "📝 VM A PLUS DE DONNEES");

        node.status({fill:"green",shape:"dot",text:"Data: " + result.totalDataPoints});
    } else {
        result.metricFound = false;
        result.message = "❌ METRIC NON TROUVE - nodered_test n'existe pas encore dans VictoriaMetrics";
        node.status({fill:"red",shape:"ring",text:"Non trouvé"});
    }
} else {
    result.metricFound = false;
    result.error = response.error || "Réponse invalide";
    result.message = "❌ ERREUR API: " + result.error;
    node.status({fill:"red",shape:"ring",text:"Erreur API"});
}

msg.payload = result;
return msg;

var result = msg.payload;

if (result.metricFound) {
    var syncInfo = {
        status: "SYNC_CHECK",
        metricName: "nodered_test",
        sentByNodeRED: result.sentByNodeRED,
        storedInVM: result.receivedByVM,
        difference: result.difference,
        conclusion: result.syncStatus,
        recommendation: result.difference > 0 ? "Attendez quelques secondes et relancez la query (délai d'ingestion VM)" : "Tout est synchronisé"
    };

    msg.payload = syncInfo;
    return msg;
}

return null;

var response = msg.payload;
var result = {
    totalMetrics: 0,
    noderedMetrics: [],
    noderedTestFound: false
};

if (response.status === "success" && response.data) {
    result.totalMetrics = response.data.length;

    response.data.forEach(function(metric) {
        if (metric.includes('nodered')) {
            result.noderedMetrics.push(metric);
        }
        if (metric === 'nodered_test') {
            result.noderedTestFound = true;
        }
    });
}

result.message = result.noderedTestFound ? 
    "✅ nodered_test TROUVE dans la liste des metrics!" : 
    "❌ nodered_test NON TROUVE dans la liste";

msg.payload = result;
return msg;

global.set('vm_success_count', 0);
global.set('vm_error_count', 0);

msg.payload = {
    status: "RESET",
    message: "Compteurs remis à zéro",
    successCount: 0,
    errorCount: 0
};

node.status({fill:"grey",shape:"ring",text:"Reset"});

return msg;
